Providers:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

Resource Blocks:
resource "aws_s3_bucket" "data" {
  bucket = "my-app-data-bucket"
  acl    = "private"
  tags = { Name = "Data Bucket" }
}

Data Sources:
data "aws_ami" "ubuntu" {
  most_recent = true
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }
}

Input Variables:
variable "instance_type" {
  description = "EC2 instance type"
  type        = string
  default     = "t3.micro"
  validation {
    condition     = contains(["t3.micro", "t3.small"], var.instance_type)
    error_message = "Instance type must be t3.micro or t3.small."
  }
}

Outputs:
output "instance_ip" {
  description = "Public IP of web instance"
  value       = aws_instance.web.public_ip
}

Locals:
locals {
  name_prefix = "${var.environment}-web"
  common_tags = { Environment = var.environment, Project = "MyApp" }
}

Dynamic Blocks:
resource "aws_security_group" "main" {
  name = "web-sg"

  dynamic "ingress" {
    for_each = var.allowed_ports
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

variable "allowed_ports" {
  default = [80, 443, 8080]
}

for_each & count:
variable "users" {
  default = {
    alice = { role = "admin" }
    bob   = { role = "viewer" }
  }
}

resource "aws_iam_user" "this" {
  for_each = var.users
  name     = each.key
  tags     = { role = each.value.role }
}

# count example
resource "aws_subnet" "public" {
  count             = length(var.availability_zones)
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = var.availability_zones[count.index]
}

Splat & Conditionals:
# Splat expressions
output "public_ips" {
  value = aws_instance.web[*].public_ip
}

# Conditional expressions
resource "aws_instance" "web" {
  instance_type = var.env == "production" ? "t3.large" : "t3.micro"
  associate_public_ip_address = var.create_eip ? true : false
}

# for expressions
output "uppercase_names" {
  value = [for name in var.names : upper(name)]
}

Remote State:
terraform {
  backend "s3" {
    bucket         = "my-terraform-state"
    key            = "prod/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
  }
}

State Locking:
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute {
    name = "LockID"
    type = "S"
  }
}

Root Module:
# root main.tf
module "networking" {
  source = "./modules/networking"
}

module "compute" {
  source = "./modules/compute"
}

Child Modules:
# modules/networking/main.tf
variable "vpc_cidr" {}
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
}
output "vpc_id" {
  value = aws_vpc.main.id
}

Module Composition:
module "network" {
  source = "terraform-aws-modules/vpc/aws"
  cidr   = "10.0.0.0/16"
}

module "app" {
  source     = "./modules/app"
  vpc_id     = module.network.vpc_id
  subnet_ids = module.network.public_subnets
}

module "database" {
  source  = "terraform-aws-modules/rds/aws"
  vpc_id  = module.network.vpc_id
  db_name = "myapp"
}

Terraform Cloud:
# terraform cloud config
terraform {
  cloud {
    organization = "myorg"
    workspaces {
      name = "myapp-prod"
    }
  }
}

