remote-exec:
provisioner "remote-exec" {
  inline = [
    "sudo apt update",
    "sudo apt install -y nginx",
    "sudo systemctl start nginx"
  ]
}

Best Practices:
resource "aws_instance" "web" {
  user_data = <<-EOF
    #!/bin/bash
    apt update && apt install -y nginx
  EOF
}

Environment Separation:
locals {
  env = terraform.workspace
  name = "${local.env}-app"
}

resource "aws_instance" "web" {
  instance_type = local.env == "production" ? "t3.large" : "t3.micro"
}

Sensitive Values:
variable "db_password" {
  type      = string
  sensitive = true
}

output "password" {
  value     = var.db_password
  sensitive = true
}

Import:
terraform import aws_instance.web i-0abcd1234efgh5678

resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t2.micro"
}

Remote State & Modules:
# Remote state with S3 + DynamoDB
terraform {
  backend "s3" {
    bucket         = "my-company-terraform-state"
    key            = "production/network/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-state-lock"
  }

  required_version = "~> 1.7"
}

# VPC module from registry
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = "myapp-vpc"
  cidr = "10.0.0.0/16"

  azs             = ["us-east-1a", "us-east-1b", "us-east-1c"]
  private_subnets = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  public_subnets  = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  enable_nat_gateway     = true
  enable_vpn_gateway     = false
  enable_dns_hostnames   = true

  tags = { Environment = "production", ManagedBy = "terraform" }
}

# Workspaces for environment separation
# terraform workspace new staging
# terraform workspace select staging

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "development"
}

resource "aws_instance" "app" {
  ami           = var.environment == "production" ? data.aws_ami.ubuntu_prod.id : data.aws_ami.ubuntu_dev.id
  instance_type = var.environment == "production" ? "t3.medium" : "t3.micro"
  subnet_id     = module.vpc.private_subnets[0]

  tags = { Name = "app-${var.environment}" }
}
